import "./App.css";

function App() {
  const workHistory = [
    {
      role: "Web Developer",
      company: "Your Company",
      period: "2023 – Present",
      description:
        "Built responsive web interfaces and improved user experience across multiple projects.",
    },
    {
      role: "Frontend Developer",
      company: "Previous Company",
      period: "2021 – 2023",
      description:
        "Developed reusable UI components and worked closely with design teams.",
    },
  ];

  const projects = [
    {
      title: "Project One",
      description: "A clean website showcasing responsive design.",
      image: "https://via.placeholder.com/400",
      link: "https://your-link.com",
    },
    {
      title: "Project Two",
      description: "A dashboard or app with modern UI.",
      image: "https://via.placeholder.com/400",
      link: "https://your-link.com",
    },
    {
      title: "Project Three",
      description: "Full-stack app with React + backend.",
      image: "https://via.placeholder.com/400",
      link: "https://your-link.com",
    },
  ];

  return (
    <div className="container">
      {/* HERO SECTION */}
      <section className="hero">
        <h1>Damian Savage</h1>
        <h3 style={{ color: "#38bdf8", marginBottom: "10px" }}>
        Aspiring Software Developer | Frontend / Full-Stack
        </h3>
        <p>Aspiring software developer with hands-on experience in full-stack development,
          currently focused on building clean, functional applications using React,
          JavaScript, and Python. Backed by a strong foundation in IT support,
          operations, and leadership, with a proven ability to adapt quickly and
          execute in high-discipline environments.</p>
      </section>

      {/* WORK HISTORY */}
      <section>
        <h2>Work History</h2>
        {workHistory.map((job, index) => (
          <div key={index} className="card">
            <h3>
              {job.role} @ {job.company}
            </h3>
            <p>{job.period}</p>
            <p>{job.description}</p>
          </div>
        ))}
      </section>

      {/* RESUME */}
      <section>
        <h2>Resume</h2>
        <p>Skills: HTML, CSS, JavaScript, React</p>
        <a href="/resume.pdf" target="_blank" rel="noreferrer">
          View Resume
        </a>
      </section>

      {/* PROJECTS */}
      <section>
        <h2>Projects</h2>
        <div className="projects">
          {projects.map((project, index) => (
            <a
              key={index}
              href={project.link}
              target="_blank"
              rel="noreferrer"
              className="project-card"
            >
              <img src={project.image} alt={project.title} />
              <h3>{project.title}</h3>
              <p>{project.description}</p>
            </a>
          ))}
        </div>
      </section>
    </div>
  );
}

export default App;
